<?php
require __DIR__.'/../app/bootstrap.php';$u=user();if(!$u||!allowed('reservations',$u)){http_response_code(403);exit('Access denied.');}$r=run('SELECT r.*,v.name AS venue FROM reservations r LEFT JOIN venues v ON v.id=r.venue_id WHERE r.id=?',[(int)($_GET['id']??0)])->fetch();if(!$r){http_response_code(404);exit('Reservation not found.');}$payments=run('SELECT * FROM payments WHERE reservation_id=? ORDER BY id',[$r['id']])->fetchAll();$paid=array_sum(array_column($payments,'amount'));
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Event statement · <?= esc($r['reference']) ?></title><link rel="stylesheet" href="assets/style.css"><style>main{max-width:850px;margin:50px auto;padding:30px}table{width:100%;border-collapse:collapse}td,th{padding:12px;border-bottom:1px solid #ddd;text-align:left}h1{font-size:42px}@media print{button{display:none}main{margin:0}}</style></head><body><main><a class="brand" href="admin/">uncorked<span>EVENT STUDIO BAR</span></a><h1 style="margin-top:45px">Event statement</h1><p><?= esc($r['reference']) ?> · <?= esc($r['status']) ?></p><p><strong><?= esc($r['name']) ?></strong><br><?= esc($r['email']) ?><br><?= esc($r['date'].' · '.$r['start'].' – '.$r['end']) ?><br><?= esc($r['venue']??'Venue not assigned') ?></p><h3>Recorded payments</h3><table><thead><tr><th>Date</th><th>Method</th><th>Reference</th><th>Amount</th></tr></thead><tbody><?php foreach($payments as $p): ?><tr><td><?= esc(substr($p['created_at'],0,10)) ?></td><td><?= esc($p['method']) ?></td><td><?= esc($p['reference']) ?></td><td><?= money($p['amount']) ?></td></tr><?php endforeach; ?></tbody></table><p>Event total: <?= money($r['total']) ?><br>Recorded payments: <?= money($paid) ?><br><strong>Remaining balance: <?= money($r['total']-$paid) ?></strong></p><p class="sample-note">Operational statement only. This is not a government-registered tax invoice or official receipt.</p><button class="button" onclick="window.print()">Print statement</button></main></body></html>
